import { z } from "zod";
import { MarkDownContent } from "../other.mjs";
import { zRenderFormats, zRenderable } from "../Renderable.mjs";
export const CatColors = [
    "cat-1",
    "cat-2",
    "cat-3",
    "cat-4",
    "cat-5",
    "cat-6",
    "cat-7",
    "cat-8",
    "cat-9",
];
export const zCatColor = z.enum(CatColors);
export const NamedColors = [
    "red",
    "blue",
    "green",
    "purple",
    "orange",
    "yellow",
    "gray",
    "pink",
    "cyan",
    "white",
    "black",
    "transparent",
];
export const zNamedColor = z.enum(NamedColors);
const SemanticColors = [
    "muted",
    "success",
    "error",
    "info",
    "warning",
    "alert",
];
export const zSemanticColor = z.enum(SemanticColors);
const RetiredColors = [
    "good", // TODO: retire
    "neutral", //retire
    "bad", // retire
    "increase", // "+"
    "flat", // "0" or "="
    "decrease", // "-"
];
// all colors
export const zColor = z.enum([
    ...SemanticColors,
    ...CatColors,
    ...NamedColors,
    ...RetiredColors,
]);
export const zProfile = z.object({
    name: zRenderable,
    subtitle: zRenderable.optional(),
    avatar: z.string().url().optional(),
});
export const zPill = z.object({
    label: zRenderable,
    icon: z.string().optional(),
    color: zColor.optional(),
});
export const zIconLabel = z.object({
    icon: z.string(),
    label: zRenderable.optional(),
    // TODO: color: zColor.optional(),
});
const zContent = z.union([
    z.string(),
    z.number(),
    z.date(),
    zProfile,
    zPill,
    zIconLabel,
    z.null(),
]);
// const zInfo = z.object({
//   icon: z.string().optional(),
//   content: z.union([z.string(), z.instanceof(MarkDownContent)]),
// });
const zInfo = z.instanceof(MarkDownContent).or(z.string());
const zTxtProps = z.object({
    content: z.union([
        // md has to go first...
        z.instanceof(MarkDownContent),
        zContent,
        z.array(zContent),
    ]),
    label: zRenderable.optional(),
    subtext: z.instanceof(MarkDownContent).or(zContent).optional(),
    size: z.enum(["xs", "s", "m", "l", "xl"]).default("m"),
    align: z.enum(["start", "end", "center"]).default("start"),
    color: zColor.optional(),
    appearance: z.enum(["card", "well", "inverse"]).optional(),
    // icon: z.string().optional(),
    format: zRenderFormats.optional(),
    info: zInfo.optional(),
    clamp: z.number().int().min(1).optional(),
});
export function Txt(define) {
    return define("Txt")
        .props(zTxtProps)
        .userEvents({
        click: [z.literal(true), false],
    })
        .render((props) => ({
        label: props.label,
        subtext: props.subtext,
        content: props.content,
        size: props.size,
        align: props.align,
        color: props.color,
        // icon: props.icon,
        appearance: props.appearance,
        format: props.format,
        info: props.info,
        clamp: props.clamp,
    }));
}
